        "key_scenes": ["密室现场勘查", "尸检发现死者肺部充满淡水但皮肤干燥", "沈砚注意到墙纸上的七条印刷规则"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "互斥的规则",
        "core_event": "沈砚整理三起案件的共性，发现三名死者都是通灵会常客，现场都有同一套通灵守则，逐条验证时发现第三条和第五条逻辑互斥，同时遵守必然违反第七条。",
        "emotional_tone": "烧脑、疑惑",
        "key_scenes": ["案件卷宗比对", "沈砚推演规则逻辑发现悖论", "苏晚上门找沈砚合作查案"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "不自觉的习惯",
        "core_event": "沈砚在办公室研究规则时，苏晚意外发现他每天寅时都会无意识地面向东方站立三分钟，刚好对应守则第六条的内容，沈砚自己才意识到这个从小养成的习惯和规则重合。",
        "emotional_tone": "震惊、诡异",
        "key_scenes": ["苏晚撞见沈砚执行第六条规则", "沈砚回忆这个习惯是从小爷爷教的", "两人前往通灵会调查"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "1842年的档案",
        "core_event": "沈砚和苏晚在公董局的档案室查找通灵会的资料，意外发现最早版本的通灵守则出现在1842年《南京条约》签订当日的一份英国商人档案里，不是近年编写的。",
        "emotional_tone": "震撼、疑惑",
        "key_scenes": ["档案室查找资料", "发现1842年的规则原件", "沈砚注意到档案上的笔迹很熟悉"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "家传的旧书",
        "core_event": "沈砚回到家中翻找爷爷留下的旧书，发现旧书上的批注笔迹和1842年档案上的笔迹完全一致，意识到自己的爷爷和这套规则有直接关联。",
        "emotional_tone": "不安、焦虑",
        "key_scenes": ["沈砚翻看家传旧书", "比对笔迹完全匹配", "赵探长上门警告沈砚停止查案"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "第四具尸体",
        "core_event": "通灵会会长被发现死在自己的密室里，死状和前三个人完全一致，现场的墙纸上新写了一行字："下一个是破规则的人"，沈砚意识到自己已经被盯上了。",
        "emotional_tone": "紧张、危机",
        "key_scenes": ["第四起命案现场", "发现威胁留言", "沈砚和苏晚决定瞒着巡捕房私下调查"]
      }
    ],
    "turning_point": "沈砚确认1842年档案上的规则笔迹属于自己的爷爷，意识到连环命案不仅是单纯的凶杀案，还牵扯到自己家族横跨百年的秘密。"
  },
  "act_two": {
    "description": "第二幕（共7.5万字，占比50%）：调查逐步深入，沈砚和苏晚遭遇层层阻碍，经历三次核心认知反转，逐渐接近规则的真相和案件的本质，同时沈砚也逐渐解开自己不自觉执行第六条规则的原因。",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "通灵会的秘密",
        "core_event": "沈砚和苏晚找到陈阿婆了解通灵会的内幕，得知所有入会的人都要先背诵七条守则，违反守则的人都会被“神明惩罚”，而且通灵会每年都会举办仪式，只有遵守所有规则的人才能参加。",
        "emotional_tone": "疑惑、探秘",
        "key_scenes": ["暗访陈阿婆", "了解通灵会的入会流程", "得知每年的仪式都在南京条约签订日举办"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "第一次反转：会长不是凶手",
        "core_event": "沈砚尸检通灵会会长的尸体，发现他的死亡时间比前三个人都早，之前出现在众人面前的会长是别人假扮的，此前推测会长是凶手的结论完全错误。",
        "emotional_tone": "震撼、颠覆",
        "key_scenes": ["尸检发现死亡时间矛盾", "证实会长早已死亡", "两人意识到凶手藏得更深"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "规则的另一面",
        "core_event": "沈砚反复研究规则逻辑，发现如果刻意违反第三条和第五条，就能触发第七条的保护机制，反而不会受到伤害，规则不是杀人的诅咒，反而更像某种操作指南。",
        "emotional_tone": "烧脑、顿悟",
        "key_scenes": ["沈砚反复推演规则逻辑", "发现规则的反向用法", "苏晚找到当年父亲留下的调查笔记"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "第二次反转：规则不是杀人预告",
        "core_event": "苏晚父亲的笔记里记录了20年前也发生过类似的密室溺毙案，当时的幸存者都是有意无意违反了第三条和第五条规则的人，证实规则是用来筛选幸存者的保护指南，而不是杀人预告。",
        "emotional_tone": "颠覆、疑惑",
        "key_scenes": ["翻阅苏父的笔记", "比对20年前的案件记录", "确认规则的保护属性"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "毒气的痕迹",
        "core_event": "沈砚重新尸检三名死者的肺部组织，发现里面有微量的特殊化学物质残留，是一种尚未被记录的气态神经毒剂，吸入后会腐蚀肺泡产生大量积水，症状和溺毙完全一致。",
        "emotional_tone": "豁然开朗、紧张",
        "key_scenes": ["高精度尸检发现化学残留", "确认死者是被毒气毒死", "两人推测密室墙纸里有毒气缓释装置"]
      },
      {
        "chapter_number": 12,
